{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment. Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets.",
      "reason": "The text describes the current state of knowledge regarding malaria control, the financial gap, and the role of optimization models in addressing this, which constitutes the context of existing knowledge and uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The text explicitly states the aim of the review, which explains the need for conducting it (to identify, characterize, and assess models for resource allocation)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not present itself as an update or replication of a previous systematic review, nor does it indicate that similar systematic reviews exist that necessitate a justification for this specific review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of optimization models for resource allocation, not a review of the effects of a specific intervention (e.g., a drug or clinical treatment) where a mechanism of action would be described."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not focus on evaluating a specific complex intervention or delivery context that requires a logic model; it is a review of modeling methodologies."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review explicitly states both the research question and the main aim/objective of the review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of models for malaria control optimization, not a review of intervention effects (e.g., a clinical trial meta-analysis), therefore PICO comparisons are not applicable."
    }
  ],
  "confidence": 100
}

{
