    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024; (3) Studies were included irrespective of the targeted geographical regions; (4) Studies were included irrespective of the population subgroups; (5) Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "The manuscript explicitly lists the inclusion criteria, covering study design (optimization models), population (human Plasmodium species), interventions (two or more), and outcomes (health benefits measured)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024",
      "reason": "The manuscript specifies report characteristics including language (English), publication status (peer-reviewed journals), and dissemination timeframe (before 30th June 2024)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not distinguish between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "table_1",
      "quote": "Table 2 Summary of models for malaria control optimization studies... Field | Frequency (%) | References... Region of focus... Number of interventions per article... Plasmodium species... Types of interventions... Population used in optimization... Administrative level of data analysis",
      "reason": "The manuscript specifies the groups used for synthesis (e.g., region of focus, number of interventions, Plasmodium species, types of interventions, population, and administrative level) in Table 2."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not provide rationales for the notable restrictions on study eligibility (e.g., why only English language studies or studies with two or more interventions were included)."
    }
  ],
  "confidence": 100
}

